"""KIVO 图标模块。base64 图标从 Tkinter 版本平移, 提供 QIcon 与着色能力。"""
from __future__ import annotations

import base64
from functools import lru_cache

from PySide6.QtCore import Qt
from PySide6.QtGui import QIcon, QPixmap, QColor, QPainter

_ICONS_B64 = {'copy': '', 'phrases': '', 'translate': '', 'ai': '', 'browser': '', 'fx': '', 'clock': '', 'calc': '', 'download': '', 'gear': '', 'star': '', 'project': 'iVBORw0KGgoAAAANSUhEUgAAADAAAAAwCAYAAABXAvmHAAAAg0lEQVR4nO3YQQ6AIAwF0Wq8/5X1AkZaCIwk89ZV+gFJMEKSJHGOZN096b3DzkRNtfneZ7q0Aow0siTEVaidtd2GtJpa2syL5qRlZpUOEfHRZ+Yj/rXKFlp2NFbG334FDEAzAM0ANAPQDEAzAM0ANAPQtg/gpZ5WuagTK0H8SJAkaZ0HxmsMM1Zne3AAAAAASUVORK5CYII=', 'voice': 'iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAYAAABzenr0AAAAfElEQVR4nO2WwQrAIAxDrez/f9lddhgjnctapWLfqWBoQ4NoKUlioF1YelTLcFRPM+DFJwPsqhl91wC7ala/RgTTDHhcqzdQ/3o/RLXncFTHiiANpIG9DYiIoNoLrf+hiUaA+seJQIONhtb3BBrP9+JvfPEjCM3o/0OyBydhRVv+p1U1MAAAAABJRU5ErkJggg=='}

_TOOL_TINTS = {'copy': ('#1D7FE0', '#DCEEFF'), 'phrases': ('#DE8A00', '#FDEEC9'), 'translate': ('#1F9D66', '#D8F3E3'), 'ai': ('#7C5CFC', '#E7E1FF'), 'fx': ('#0CA6A0', '#D2F1EF'), 'clock': ('#5B6EE1', '#E0E4FC'), 'calc': ('#EE5B7F', '#FDE0E8'), 'download': ('#F06423', '#FEE3D3'), 'gear': ('#5B7A99', '#E2EBF3'), 'star': ('#E8A13A', '#FCEFD2')}


def _raw_pixmap(name: str) -> QPixmap:
    pm = QPixmap()
    pm.loadFromData(base64.b64decode(_ICONS_B64[name]))
    return pm


@lru_cache(maxsize=None)
def icon(name: str) -> QIcon:
    return QIcon(_raw_pixmap(name))


@lru_cache(maxsize=None)
def tinted_icon(name: str, color: str) -> QIcon:
    """把单色线条图标着成指定颜色 (用于深色背景/选中态)。"""
    src = _raw_pixmap(name)
    out = QPixmap(src.size())
    out.fill(Qt.transparent)
    p = QPainter(out)
    p.drawPixmap(0, 0, src)
    p.setCompositionMode(QPainter.CompositionMode_SourceIn)
    p.fillRect(out.rect(), QColor(color))
    p.end()
    return QIcon(out)


def tool_colors(name: str):
    """返回 (主色, 浅底) 工具配色。"""
    return _TOOL_TINTS.get(name, ("#007AFF", "#E9F2FF"))
